INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (103, 'EAN Congress', 'EAN', 'https://www.ean.org/congress2027', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'TYPO3 landing page /congress2027. Congress dates (12-15 June 2027) only appear in the meta description; the body lists session dates first (13 June), so a synthetic header line from og:description is used. Place from ''takes place at <Venue>, <City>, <Country>''. Fees on /congress2027/register/registration (table, EUR, early/regular/late/virtual per category). Abstract key dates on /abstracts/public-submission-instructions.'),
  (104, 'AAIC', 'AAIC', 'https://aaic.alz.org/overview.asp', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Custom ASP.NET microsite; header lines give ''July 18-21, 2027 | Chicago, United States, and Online''; the title line carries the organiser, not a place. Venue (McCormick Place) from the ''Conference Location'' block. Abstract dates: /abstracts/overview.asp Important Dates table is Date | Event; <tr> cells are read directly. General abstract deadline 11 Jan 2027 (ISTAART deadline 18 Jan is a different row); submission opening is ''Mid November 2026'' (vague, so abstract_open false, no date invented).'),
  (105, 'AUA Annual Meeting', 'AUA', 'https://www.auanet.org/AUA2027', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Cold Fusion site, www.auanet.org/AUA2027. No dated body line: the only date is the meta description (''May 21 - 24, 2027 in San Diego,CA''). Nav links are relative to /AUA2027/ but the URL has no trailing slash, so sub-pages are given explicitly (key-dates). Registration opens 2 Dec 2026; no fees yet. Site notice forbids feeding AUA content to AI tools, so description is a deterministic meta sentence and no LLM call is made.'),
  (106, 'AAO Annual Meeting', 'AAO', 'https://www.aao.org/annual-meeting', 'conference', 'single_page', NULL, 1, FALSE, FALSE, 'aao.org/annual-meeting is the finished AAO 2026 page. The next edition is listed on /annual-meeting/past-and-future-meetings under ''Future Meetings'' as three lines: ''AAO 2027'' / ''Las Vegas, Venetian Expo & Hotel'' / ''Nov. 12-15: AAO 2027''. Bespoke edition parser; no fees or abstracts published yet.'),
  (107, 'RSNA Annual Meeting', 'RSNA', 'https://www.rsna.org/annual-meeting', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Sitecore site. Annual-meeting page header ''Annual Meeting: Nov. 29 - Dec. 3, 2026''; place from the pricing page (McCormick Place, Chicago). Pricing page /annual-meeting/attendee-resources/pricing-and-registration has three matrices (member packages as text, select member categories and non-member registrant types as HTML tables) parsed from raw <table> cells.'),
  (108, 'CHEST Annual Meeting', 'CHEST', 'https://www.chestnet.org/learning-and-events/events/chest-annual-meeting', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'CHEST event page shows the current edition as year-less header lines (''October 18 to 21 | CHEST Annual Meeting'', ''CHEST 2026'') and a ''save the dates'' list (''2027: October 24-27 | Vancouver, BC, Canada''). Bespoke edition parser: header edition while it has not ended, otherwise the next entry of the list. Fees are not parsed.'),
  (109, 'BOFAS Annual Scientific Meeting', 'BOFAS', 'https://www.bofas.org.uk/annual-meeting', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'DNN site, /annual-meeting redirects to /annual-meeting/home. Home text ''BOFAS 2026 will be held in Wales from 4th to 6th of November''. Venue and city from /annual-meeting/venue. Fees are a PDF (''2026 Registration Rates Newport.pdf'') linked from /annual-meeting/registration, read with pypdf.'),
  (110, 'BPNA Conference', 'BPNA', 'https://bpna.org.uk/conference/2027/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Custom PHP site, /conference/2027/. Header: ''...will take place on 6-8 January 2027 as a hybrid event at:'' then venue, street, city, postcode. Fees on the ''Booking Details'' page (index.php?contentid=N, id changes yearly; found from the nav link) as one-cell-per-line tables for full, day, social and virtual rates, three price columns (early/standard/late).'),
  (111, 'ACC Scientific Session', 'ACC', 'https://accscientificsession.acc.org/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Dedicated Sitecore event site accscientificsession.acc.org. Home: ''ACC.27-WCC ... April 10 - 12, 2027 in Houston, TX''. Venue from the Travel page (''will take place at the George R. Brown Convention Center''). Fees: four <h2>+<table> packages (PLUS, in-person, @Home virtual, Expo only) on Registration Rates & Dates. Abstract state from the Late-Breaking Clinical Trials page.'),
  (112, 'ASN Kidney Week', 'ASN', 'https://www.asn-online.org/education/kidneyweek/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'ASP.NET site. Kidney Week 2026 (Denver, 21-25 Oct) landing page; year-specific sub-pages register-overview.aspx and important-dates.aspx are linked from it. Fees are <h4>program + table (Early/Standard/Onsite) blocks; Important Dates lists the date line before its label.'),
  (113, 'ASA Annual Meeting', 'ASA', 'https://www.asahq.org/annualmeeting', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Sitecore. /annualmeeting shows ''Thank you for making ANESTHESIOLOGY 2026 a success'' and the next edition as one pipe line: ''ANESTHESIOLOGY 2027 | October 15- 19 | Boston, MA | Thomas M. Menino Convention & Exhibition Center'' (stray space in the range). Abstract schedule on /annualmeeting/education/submissions. Registration page still describes 2026.'),
  (114, 'UEG Week', 'UEG', 'https://ueg.eu/week', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'ueg.eu/week shows the current congress (UEG Week 2026, Barcelona 17-20 Oct, just finished) and ends with a ''UEG Week 2027 / October 16 - 19, 2027 / Bella Center Copenhagen, Denmark'' block for the next edition. Family finds the 2027 block; hooks add the city and keep 2026 blurbs, fee pages, CME and abstract text out of the 2027 row.'),
  (115, 'BAAPS Annual Conference', 'BAAPS', 'https://baaps.org.uk/about/events/', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'BAAPS /about/events is a calendar of many events, not one congress, so this is a bespoke extractor on the rcpath.py pattern (single_congress family does not fit). Walks /about/events/date/<YYYY>/ for this year and the next two (div.date_row cards), keeps unfinished events whose page is plastic/aesthetic-surgery related or organised by BAAPS (the calendar also carries unrelated nursing/healthcare promoter listings), then reads each detail page. Fees come from the organiser''s own site JSON-LD where linked; BAAPS-booked events are behind login.'),
  (130, 'British Society of Gastroenterology (BSG)', 'British Society of Gastroenterology', 'https://www.bsg.org.uk/events', 'mixed', 'page_query', 'https://www.bsg.org.uk/events?page={n}&start={today}', 3, FALSE, TRUE, 'Kentico + Blazor; cards are server-prerendered. Walk /events?page=N&start=<today> (the start param is required for page 2, else the unfiltered 100-event archive is returned) until the pager total is reached. Cards give title, dd-mm-yyyy @ hh:mm range and location; event type comes from the title. Detail has a Registration fees block of ''label:'' / ''£amount'' lines.'),
  (131, 'British Orthopaedic Association (BOA)', 'British Orthopaedic Association', 'https://www.boa.ac.uk/learning-and-events/ems-event-calendar.html', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Eventfolio (Preside) calendar; listing comes from the public JSON endpoint /ems/eventCalendar/ajaxResults/ (offset/page_size), same card HTML. Detail pages have a structured header (.event-date/.event-venue/.event-pricing) and a Booking widget. External/Non-BOA rows are stubs; the Go-to-event-website link is kept as organiser_url. Booking pages are login-walled. 2027 Annual Congress is read from the future-congresses page.'),
  (132, 'ESCRS Meetings & Events', 'ESCRS', 'https://www.escrs.org/meetings-and-events/event-search', 'conference', 'single_page', NULL, 1, TRUE, TRUE, 'Umbraco event-search: cards are server-rendered (default filter = upcoming); date lines have no year for this year''s events (year from URL slug or next occurrence). Load-more only appears above ~96 cards. Annual events (Winter Meeting, Congress) are empty shells on escrs.org: details come from the wintermeeting/congress microsites when they name the same year. Education events (Vision to Venture) reach public EUR ticket prices via /v2v/ page -> members.escrs.org/event/. Affiliated events link to the organiser (Outlook SafeLink unwrapped).'),
  (133, 'Intensive Care Society (ICS)', 'Intensive Care Society', 'https://ics.ac.uk/events/calendar.html', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Eventfolio (Preside) calendar, same platform as boa.ac.uk; listing from the public JSON endpoint /ems/eventCalendar/ajaxResults/ (card HTML). Detail header has .event-date/.event-time/.event-venue; fees only in the Booking widget (booking pages are login-walled). The SOA congress card is a stub: real info and image-only fee tables are on /events/soaNN.html and /events/soaNN/tickets.html (vision). On-demand rows skipped.')
